def solve(s):
    """Reverses case of alphabets in the given string, keeping non-alphabets as they are."""
    result = ""
    for char in s:
        if char.lower() in string.ascii_letters:
            if char.islower():
                result += char.upper()
            else:
                result += char.lower()
        else:
